// Hosted Core-only workload. Reuse frozen input saves for comparable behavior and food budgets.
// Timers exclude encoding; repeated final hashes detect nondeterminism, not native frame rate.
using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Text.Json;using System.Security.Cryptography;using Outbreak.Core;using Outbreak.Contracts;using Outbreak.Persistence;
class MovementLoad{static string State(World w)=>Documents.Encode(w.Capture());static void Main(string[]args){Directory.CreateDirectory(args[0]);foreach(var scene in new[]{(6,5,2),(8,8,4)}){string key=$"{scene.Item1}-{scene.Item2}-{scene.Item3}";string input=Path.Combine(args[0],key+".obsave");if(!File.Exists(input)){var w=CitySetup.Create(214,scene.Item1,scene.Item2,scene.Item3,CityStreetLayout.Staggered,CityZoning.NeighborhoodCenters);int food=w.FoodSupplies().RemainingMeals;var s=w.Capture();foreach(var a in s.actors){var b=Array.Find(s.map.storageBoxes,b=>w.HouseAt(b.x,b.y)==a.assignedHouseId);if(b==null)throw new Exception("No household box");var stack=Array.Find(b.items,i=>i.item==InventoryItem.Food);stack.quantity+=a.carriedFood;}for(int i=0;i<s.actors.Length;i++){var a=s.actors[i];a.hunger=80;a.carriedFood=0;s.actors[i]=a;}w=World.Restore(s);if(w.FoodSupplies().RemainingMeals!=food)throw new Exception("Food budget changed");File.WriteAllText(input,State(w));}string start=File.ReadAllText(input);var warm=Documents.ParseSave(start);for(int t=0;t<100;t++)warm.Step();var runs=new object[3];string expected=null;for(int pass=0;pass<3;pass++){var w=Documents.ParseSave(start);double[] times=new double[250];GC.Collect();long allocated=GC.GetAllocatedBytesForCurrentThread();for(int t=0;t<times.Length;t++){long tick=Stopwatch.GetTimestamp();w.Step();times[t]=(Stopwatch.GetTimestamp()-tick)*1000.0/Stopwatch.Frequency;}long bytes=GC.GetAllocatedBytesForCurrentThread()-allocated;string finish=State(w);if(expected!=null && finish!=expected)throw new Exception("Nondeterministic workload");expected=finish;Array.Sort(times);runs[pass]=new{totalMs=times.Sum(),meanMs=times.Average(),p95Ms=times[(int)(times.Length*.95)],maxMs=times.Last(),allocatedBytes=bytes};}var result=new{scenario=key,count=warm.Count,kind="Synchronized hungry generated-city load; carried food transferred to owned pantry, total finite meals unchanged",rules=warm.Capture().rulesVersion,ticks=250,runs,finalSha256=Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(expected))),nativeRendering="excluded"};File.WriteAllText(Path.Combine(args[0],key+".json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));}}}
